'use strict';
/* One explanation per risk. This layer never writes completion or acknowledgment. */
window.PhoenixWarningCatalog={
 context(task,stage){if(task==='q-lilac')return stage==='1'?'poi-4':stage==='4'?'departure':null;if(task==='q-beast'&&stage==='trophy')return 'poi-4';if(task==='q-incident'&&['1','2'].includes(stage))return 'departure';if(task==='q-death'&&stage==='3')return task;return null;},
 hub(task){if(['q-lilac','q-beast'].includes(task))return 'poi-4';if(task==='q-incident')return 'departure';return ['q-firestarter','q-missing','q-death'].includes(task)?task:null;},
 get(id,tasks){
  if(id==='poi-4')return {id,title:tasks[id].name,short:'Optional missable: collect the crystal skull before completing the griffin quest.',consequence:'The optional crystal skull can no longer be collected after The Beast of White Orchard is completed. It is a keepsake, not an equipment upgrade.',cutoff:'Collect it before finishing The Beast of White Orchard. This cutoff is earlier than the White Orchard departure.',prevention:'Use Witcher Senses at the opening campsite and collect the skull before reporting the completed hunt. Check in game if your guide record is uncertain.',href:'#'+tasks[id].view,action:'Open crystal skull entry and location'};
  if(id==='departure')return {id,title:'White Orchard departure risks',short:'Departure risk: finish the three sensitive quests before the final inn conversation.',consequence:'Unfinished Missing in Action, Twisted Firestarter and On Death’s Bed can fail as the departure sequence reaches Imperial Audience. Returning to White Orchard later does not restore failed quests.',cutoff:'Finish the quests you want before speaking to Vesemir at the inn after the griffin hand-in. That conversation starts the departure sequence.',prevention:'Check your in-game journal and the shared departure review before the final inn conversation. Guide records alone do not establish what you completed in game.',href:'#'+tasks['departure-review'].view,action:'Open departure review'};
  if(['q-firestarter','q-missing','q-death'].includes(id))return {id,title:tasks[id].name+' · departure risk',short:'Departure-sensitive quest: finish before the final inn conversation.',consequence:tasks[id].name+' can fail if left unfinished when the departure sequence reaches Imperial Audience. Returning later does not restore it.',cutoff:'Finish before speaking to Vesemir at the inn after the griffin hand-in.',prevention:'Check the quest in your in-game journal and finish its remaining objectives before starting the departure sequence.',href:'#'+tasks[id].view+'/'+tasks[id].stages[0].id,action:'Open relevant walkthrough step'};
  return null;
 }
};
window.createPhoenixWarningDetails=function({tasks,navigate}){
 const catalog=window.PhoenixWarningCatalog,viewport=()=>window.PhoenixViewport||window;
 const make=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;};
 const dialog=make('dialog',null,'warning-details-dialog');dialog.setAttribute('aria-labelledby','warning-details-title');
 const paper=make('article',null,'reading-panel warning-details-paper'),header=make('header'),title=make('h2');title.id='warning-details-title';
 const closeButton=make('button','Close ×','warning-details-close');closeButton.type='button';closeButton.setAttribute('aria-label','Close warning details');header.append(title,closeButton);
 const body=make('div'),actions=make('div',null,'warning-details-actions'),source=make('button',null,'warning-details-source');source.type='button';actions.append(source);paper.append(header,body,actions);dialog.append(paper);document.body.append(dialog);
 let origin=null,current=null,returnControl=null,returnOriginal=null,activeReturn=null;
 const route=()=>location.hash||'#home';
 function clearReturn(){if(!returnControl)return;if(returnOriginal){returnControl.textContent=returnOriginal.text;returnControl.onclick=returnOriginal.onclick;returnControl.hidden=returnOriginal.hidden;returnControl.classList.remove('warning-source-return');}else returnControl.remove();returnControl=null;returnOriginal=null;}
 function installReturn(marker){const view=document.getElementById(location.hash.slice(1).split('/')[0]);if(!view)return;returnControl=view.querySelector('[data-exploration-return],[data-diagram-return],.departure-return');if(returnControl){returnOriginal={text:returnControl.textContent,onclick:returnControl.onclick,hidden:returnControl.hidden};returnControl.hidden=false;returnControl.classList.add('warning-source-return');}else{returnControl=make('button',null,'warning-source-return');returnControl.type='button';(view.querySelector('.reading-panel')||view).prepend(returnControl);}returnControl.textContent='Return to where I came from';returnControl.onclick=()=>history.back();activeReturn=marker;}
 function finish(followingSource=false){if(!origin)return;const saved=origin;origin=null;window.PhoenixViewport?.unlock();if(dialog.open)dialog.close();if(route()===saved.hash){viewport().scrollTo(0,saved.y);if(saved.focus?.isConnected)saved.focus.focus({preventScroll:true});if(saved.menuReturn&&followingSource!==true)requestAnimationFrame(()=>window.dispatchEvent(new CustomEvent('phoenix:warning-menu-return',{detail:saved.menuReturn})));}}
 function open(id,trigger,options={}){const detail=catalog.get(id,tasks);if(!detail)return;if(dialog.open)finish();current=detail;origin={hash:route(),y:viewport().scrollY,focus:trigger,menuReturn:options.menuReturn||null};title.textContent=detail.title;body.replaceChildren();for(const [label,text]of [['Consequence',detail.consequence],['Cutoff',detail.cutoff],['How to avoid it',detail.prevention]])body.append(make('h3',label),make('p',text));source.textContent=detail.action;window.PhoenixViewport?.lock();dialog.showModal();closeButton.focus({preventScroll:true});}
 closeButton.onclick=finish;dialog.addEventListener('cancel',e=>{e.preventDefault();finish();});dialog.addEventListener('close',finish);
 dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=paper.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)finish();});
 source.onclick=()=>{const saved=origin,destination=current.href;finish(true);if(destination===saved.hash)return;navigate(destination);const marker={hash:saved.hash,y:saved.y,menuReturn:saved.menuReturn};history.replaceState({...history.state,warningDetailsOrigin:marker},'',location.href);clearReturn();installReturn(marker);};
 function shortWarning(node,id){if(!node||node.hidden)return;const d=catalog.get(id,tasks);if(!d)return;node.replaceChildren(make('span',d.short));const b=make('button','Full warning details','warning-details-trigger');b.type='button';b.dataset.warningDetails=id;node.append(b);}
 function refresh(){if(origin&&origin.hash!==route())finish();const returning=activeReturn&&route()===activeReturn.hash?activeReturn:null;clearReturn();activeReturn=null;const marker=history.state?.warningDetailsOrigin;if(marker&&typeof marker.hash==='string'&&Number.isFinite(marker.y))installReturn(marker);if(returning)requestAnimationFrame(()=>requestAnimationFrame(()=>requestAnimationFrame(()=>{viewport().scrollTo(0,returning.y);if(returning.menuReturn)window.dispatchEvent(new CustomEvent('phoenix:warning-menu-return',{detail:returning.menuReturn}));})));
  for(const m of window.PhoenixQuestHubs.models.values()){const id=catalog.hub(m.q);if(id)shortWarning(m.warning,id);}
  for(const [id,t]of Object.entries(tasks)){if(!t.stages)continue;for(const st of t.stages){const risk=catalog.context(id,st.id);if(risk)shortWarning(document.querySelector('#'+t.view+' [data-stage="'+st.id+'"] .stage-content>.risk-note'),risk);}}
  shortWarning(document.getElementById(tasks['q-beast'].view).querySelector('.reading-panel>.risk-note'),'poi-4');
 }
 document.addEventListener('click',e=>{const b=e.target.closest('[data-warning-details]');if(b&&!b.closest('dialog')){e.preventDefault();open(b.dataset.warningDetails,b);}});
 for(const event of ['phoenix:route-rendered','phoenix:progress-committed','phoenix:progress-undone'])addEventListener(event,refresh);refresh();return {open,close:finish,refresh};
};
